import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-011 — Decisions apply project-wide: no partial updates, and screenshots after each slice","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-011-decisions-apply-project-wide.md","filePath":"uxs/decisions/UXD-011-decisions-apply-project-wide.md"}'),i={name:"uxs/decisions/UXD-011-decisions-apply-project-wide.md"};function n(r,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-011-—-decisions-apply-project-wide-no-partial-updates-and-screenshots-after-each-slice" tabindex="-1">UXD-011 — Decisions apply project-wide: no partial updates, and screenshots after each slice <a class="header-anchor" href="#uxd-011-—-decisions-apply-project-wide-no-partial-updates-and-screenshots-after-each-slice" aria-label="Permalink to &quot;UXD-011 — Decisions apply project-wide: no partial updates, and screenshots after each slice&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (a process decision)</li><li><strong>Date</strong>: 2026-11-11 (proposed and decided)</li><li><strong>Decider</strong>: the operator — &quot;we cannot have partial updates, we have to sync the entire project with all decisions we are doing. quality over speed&quot; and &quot;provide smaller screenshots after each segment so I can visually validate&quot; (operator note <code>decisions-apply-project-wide</code>, modified 2026-11-11); &quot;Definition of done — every slice (operator, 2026-11-11: no partial updates, quality over speed)&quot; and &quot;Checks and balances (operator, 2026-11-11: invest time up front)&quot; (<code>docs/wip/2026-11-11-ux-feedback-plan.md</code> lines 467 and 483)</li><li><strong>Answers</strong>: the whole feedback list; every slice</li><li><strong>Changes</strong>: UXS-000 §How a UX change moves and §Definition of done (this series). AGENTS.md has no line for it yet.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A decision applied to the screens that were looked at but not to the rest leaves the site inconsistent, which is what the operator&#39;s feedback list was about (operator note <code>decisions-apply-project-wide</code>).</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>The sources record the rule and no alternatives.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>A decision is applied everywhere in one pass</strong>: every route and component in <code>src/</code> (a repo-wide search, not the sample screens), the docs that state the rule, the tests that guard it, and all 14 locales for any text. The slice is not done until a repo-wide search shows no leftover outside a documented allow-list.</li><li><strong>Tests move with the work</strong>: expectations changed by the decision are adjusted, new tests guard the rule (site-wide where possible), obsolete tests are removed; no suite is left red or skipped.</li><li><strong>Each slice runs the same way</strong>: a read-only brief first; implementation against it; an independent checker that did not write the code re-runs the searches and the suites; the lead reads the evidence and the screenshots, then reports (plan lines 483–494).</li><li><strong>Screenshots after each slice</strong>: a small set of downscaled before/after shots, desktop 13-inch laptop and phone, for the operator to validate visually.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Slices are larger and slower; the operator chose that (&quot;quality over speed&quot;).</li><li>A decision cannot ship as a sample: for example the type floor (<a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a>) was applied across 121 files at once rather than to the panels the operator pointed at.</li><li>Each new decision gets a UXD before the slice is called done (UXS-000 definition of done, item 5).</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Process, not code. The checker&#39;s evidence (searches and suites with their output) is the record; the checks are re-run by an agent other than the implementer.</p>',12)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
